import { useState } from 'react';
import FroalaEditorComponent from 'react-froala-wysiwyg';
import 'froala-editor/css/froala_style.min.css';
import 'froala-editor/css/froala_editor.pkgd.min.css';
import 'froala-editor/js/plugins.pkgd.min.js';

const config = {
  key: 'TRIAL-LICENSE-KEY-FOR-FROALA-NOT-FOR-PRODUCTION-USE',
  // Set custom buttons.
  toolbarButtons: {
    // Undo and redo first. A group that shows all its buttons needs no more button.
    'history': {
      'buttons': ['undo', 'redo']
    },
    'moreText': {
      'buttons': ['bold', 'italic', 'underline', 'strikeThrough', 'subscript', 'superscript', 'fontFamily', 'fontSize', 'textColor', 'backgroundColor', 'inlineClass', 'inlineStyle', 'clearFormatting']
    },
    'moreParagraph': {
      'buttons': ['alignLeft', 'alignCenter', 'formatOLSimple', 'alignRight', 'alignJustify', 'formatOL', 'formatUL', 'paragraphFormat', 'paragraphStyle', 'lineHeight', 'outdent', 'indent', 'quote']
    },
    'moreRich': {
      // fontAwesome and embedly show only with their third-party plugins loaded.
      'buttons': ['insertLink', 'insertImage', 'insertVideo', 'insertTable', 'emoticons', 'fontAwesome', 'specialCharacters', 'embedly', 'insertFile', 'insertHR']
    },
    'moreMisc': {
      // spellChecker shows only with its third-party plugin loaded.
      'buttons': ['fullscreen', 'print', 'getPDF', 'spellChecker', 'selectAll', 'html', 'help']
    }
  },
  // Change buttons for XS screen.
  toolbarButtonsXS: [['undo', 'redo'], ['bold', 'italic', 'underline']]
};

export default function App() {
  const [model, setModel] = useState('<p>You have full control over the rich text editor\'s toolbar functionality. Simply customize what buttons are available, their order in the toolbar and also group them the way you want.</p>');

  return <FroalaEditorComponent tag="textarea" config={config} model={model} onModelChange={setModel} />;
}

