import { useState } from 'react';
import FroalaEditorComponent from 'react-froala-wysiwyg';
import 'froala-editor/css/froala_style.min.css';
import 'froala-editor/css/froala_editor.pkgd.min.css';
import 'froala-editor/js/plugins.pkgd.min.js';
import DOMPurify from 'dompurify';

// Your app's own helpers. These stand-ins keep the example running.
// Replace them with your sign-in, your sanitizer setup and your analytics.
function getUserToken() {
  return 'USER_SESSION_TOKEN';
}

function getCurrentUserId() {
  return 'user-42';
}

function sanitizeHTML(html) {
  return DOMPurify.sanitize(html);
}

function trackAIUsage(name) {
  // Send the name to your analytics.
}

const config = {
  key: 'TRIAL-LICENSE-KEY-FOR-FROALA-NOT-FOR-PRODUCTION-USE',
  toolbarButtons: ['aiAssist'],
  // Every AI feature needs it. It accepts the Froala AI Supplemental Terms.
  aiSupplementalTermsAccepted: true,

  aiAssistRequest: async function (data, signal) {
    try {
      const response = await fetch('https://your-backend.com/api/ai', {
        method: 'POST',
        headers: {
          'Authorization': 'Bearer ' + getUserToken(),
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          prompt: data.prompt,
          context: data.context,
          user_id: getCurrentUserId()
        }),
        signal: signal
      });

      if (!response.ok) {
        throw new Error('AI request failed: ' + response.statusText);
      }

      const result = await response.json();

      // Validate response
      if (!result.success) {
        throw new Error(result.error || 'Unknown error');
      }

      return result.data.content;

    } catch (error) {
      console.error('AI request error:', error);
      throw error;
    }
  },

  events: {
    'aiAssist.beforeInsert': function (content) {
      // Sanitize content before insertion
      const sanitized = sanitizeHTML(content);
      return sanitized.length > 0;
    },

    'aiAssist.afterInsert': function () {
      // Track usage
      trackAIUsage('content_inserted');
    }
  }
};

export default function App() {
  const [model, setModel] = useState('');

  return <FroalaEditorComponent tag="textarea" config={config} model={model} onModelChange={setModel} />;
}

