import { useState } from 'react';
import FroalaEditorComponent from 'react-froala-wysiwyg';
import 'froala-editor/css/froala_style.min.css';
import 'froala-editor/css/froala_editor.pkgd.min.css';
import 'froala-editor/js/plugins.pkgd.min.js';

const config = {
  key: 'TRIAL-LICENSE-KEY-FOR-FROALA-NOT-FOR-PRODUCTION-USE',
  toolbarButtons: ['aiAssist'],
  // Every AI feature needs it. It accepts the Froala AI Supplemental Terms.
  aiSupplementalTermsAccepted: true,
  aiAssistRequest: async function(data, signal) {
    const response = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer YOUR_OPENAI_API_KEY',
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: 'gpt-4',
        messages: [
          {
            role: 'system',
            content: 'You are a helpful writing assistant. Always respond in valid HTML format.'
          },
          {
            role: 'user',
            content: data.prompt
          }
        ],
        max_tokens: 1000,
        temperature: 0.7
      }),
      signal: signal
    });

    const result = await response.json();
    return result.choices[0].message.content;
  }
};

export default function App() {
  const [model, setModel] = useState('');

  return <FroalaEditorComponent tag="textarea" config={config} model={model} onModelChange={setModel} />;
}

