import { useRef, useState } from 'react';
import FroalaEditorComponent from 'react-froala-wysiwyg';
import 'froala-editor/css/froala_style.min.css';
import 'froala-editor/css/froala_editor.pkgd.min.css';

const config = {
  key: 'TRIAL-LICENSE-KEY-FOR-FROALA-NOT-FOR-PRODUCTION-USE',
  toolbarButtons: [['undo', 'redo'], ['paragraphFormat'], ['bold', 'italic', 'underline'], ['insertLink', 'insertImage'], ['formatUL', 'formatOL']]
};

export default function App() {
  const [model, setModel] = useState('<p>The buttons below will destroy and init the rich text editor again.</p>');
  // initialize, destroy and getEditor, handed over when the component mounts.
  const controls = useRef(null);

  // With onManualControllerReady the component waits, so this starts the editor the first time.
  function ready(c) {
    controls.current = c;
    c.initialize();
  }

  return (
    <>
      <FroalaEditorComponent config={config} model={model} onModelChange={setModel} onManualControllerReady={ready} />
      <p>
        <button type="button" onClick={() => controls.current.destroy()}>Destroy</button>
        <button type="button" onClick={() => controls.current.initialize()}>Init</button>
      </p>
    </>
  );
}

