FroalaEditor.RegisterCommand('export', {
  title: 'Export from Markdown',
  type: 'button',
  undo: false,
  refreshAfterCallback: true,
  forcedRefresh: true,
  disabled: true,
  plugin: 'markdown',
  showOnMobile: true,
  refresh: function ($btn) {
    var off = !this.markdown.isEnabled();
    $btn[0].classList.toggle('fr-disabled', off);
    $btn[0].setAttribute('aria-disabled', off);
  },
  callback: function () {
    this.selection.save();
    this.commands.selectAll();
    const markdownContent = this.selection.text();
    this.selection.restore();
    const blob = new Blob([markdownContent], {
      type: 'text/markdown;charset=utf-8',
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'markdown.md';
    a.click();
    URL.revokeObjectURL(url);
  }
});

