import { useState } from 'react';
import FroalaEditor from 'froala-editor';
import FroalaEditorComponent from 'react-froala-wysiwyg';
import 'froala-editor/css/froala_style.min.css';
import 'froala-editor/css/froala_editor.pkgd.min.css';
import 'froala-editor/js/plugins.pkgd.min.js';
import './App.css';

// Tribute.js, from the script in index.html
var tribute = new window.Tribute({
  values: [
    { key: 'Phil', value: 'pheartman' },
    { key: 'Gordon', value: 'gramsey' },
    { key: 'Jacob', value: 'jacob' },
    { key: 'Ethan', value: 'ethan' },
    { key: 'Emma', value: 'emma' },
    { key: 'Isabella', value: 'isabella' }
  ],
  selectTemplate: function (item) {
    return '<span class="fr-deletable fr-tribute">' + item.original.key + '</span>';
  }
});

const config = {
  key: 'TRIAL-LICENSE-KEY-FOR-FROALA-NOT-FOR-PRODUCTION-USE',
  toolbarButtons: [['undo', 'redo'], ['paragraphFormat'], ['bold', 'italic', 'underline'], ['insertLink', 'insertImage'], ['formatUL', 'formatOL']],
  events: {
    initialized: function () {
      var editor = this;

      tribute.attach(editor.el);

      editor.events.on('keydown', function (e) {
        if (e.which == FroalaEditor.KEYCODE.ENTER && tribute.isActive) {
          return false;
        }
      }, true);
    }
  }
};

export default function App() {
  const [model, setModel] = useState('<p>Froala WYSIWYG Editor can easily be integrated with the awesome <a href="https://github.com/zurb/tribute" target="_blank" rel="nofollow">Tribute.js library</a>. Type an @ to display the autocomplete list.</p>');

  return <FroalaEditorComponent tag="textarea" config={config} model={model} onModelChange={setModel} />;
}

